create extension if not exists "pgcrypto";
create table if not exists "user" (id uuid primary key default gen_random_uuid(), name text not null, email text not null unique, "emailVerified" boolean not null default false, image text, "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now());
do $$ begin if to_regclass('auth.users') is not null then execute 'insert into public."user" (id,name,email,"emailVerified","createdAt","updatedAt") select id,split_part(email,''@'',1),email,email_confirmed_at is not null,created_at,coalesce(updated_at,created_at) from auth.users where email is not null on conflict (id) do nothing'; end if; end $$;
create table if not exists session (id uuid primary key default gen_random_uuid(), "expiresAt" timestamptz not null, token text not null unique, "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now(), "ipAddress" text, "userAgent" text, "userId" uuid not null references "user"(id) on delete cascade);
create index if not exists session_user_id_idx on session ("userId");
create table if not exists account (id uuid primary key default gen_random_uuid(), "accountId" text not null, "providerId" text not null, "userId" uuid not null references "user"(id) on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now());
create index if not exists account_user_id_idx on account ("userId");
create table if not exists verification (id uuid primary key default gen_random_uuid(), identifier text not null, value text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz not null default now(), "updatedAt" timestamptz not null default now());
create index if not exists verification_identifier_idx on verification (identifier);
do $$ declare r record; begin for r in select c.conname,c.conrelid::regclass table_name from pg_constraint c where c.contype='f' and pg_get_constraintdef(c.oid) like '%auth.users%' loop execute format('alter table %s drop constraint %I',r.table_name,r.conname); execute format('alter table %s add constraint %I foreign key (user_id) references public."user"(id) on delete cascade',r.table_name,r.conname); end loop; end $$;
do $$ declare table_name text; begin foreach table_name in array array['certifications','modules','subscriptions','user_progress','questions','simulado_attempts','flashcards','user_flashcard_progress'] loop if to_regclass('public.' || table_name) is not null then execute format('alter table public.%I disable row level security', table_name); end if; end loop; end $$;
